Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of *all* tooltips. Instead, you must lift the state up to a Context Provider that wraps your entire application (or the specific section where tooltips are used).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state of the tooltips.

`context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of a tooltip instance
interface TooltipInstance {
  id: string;
  content: string;
  position: 'top' | 'bottom' | 'left' | 'right';
}

interface TooltipContextType {
  openTooltip: (id: string, content: string, position: 'top' | 'bottom' | 'left' | 'right') => void;
  closeTooltip: (id: string) => void;
  isOpen: (id: string) => boolean;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // We use a Map to store multiple open tooltips if needed, 
  // but for this example, we will enforce a "single active" logic 
  // or allow multiple by ID. Let's allow multiple by ID for flexibility.
  const [activeTooltips, setActiveTooltips] = useState<Record<string, TooltipInstance>>({});

  const openTooltip = useCallback((id: string, content: string, position: 'top' | 'bottom' | 'left' | 'right') => {
    setActiveTooltips((prev) => ({
      ...prev,
      [id]: { id, content, position },
    }));
  }, []);

  const closeTooltip = useCallback((id: string) => {
    setActiveTooltips((prev) => {
      const { [id]: removed, ...rest } = prev;
      return rest;
    });
  }, []);

  const isOpen = useCallback((id: string) => {
    return activeTooltips[id] !== undefined;
  }, [activeTooltips]);

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, isOpen }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

